require("dotenv").config();
const fs = require("fs");
const path = require("path");
const puppeteer = require("puppeteer");
const readline = require("readline");
const axios = require("axios");
const FormData = require("form-data");
const rimraf = require("rimraf");

const IS_HEADLESS = process.env.HEADLESS === "1" || process.argv.includes("--headless");
const TELEGRAM_TOKEN = process.env.TELEGRAM_TOKEN;
const TELEGRAM_CHAT_ID = process.env.TELEGRAM_CHAT_ID;
const AKUN_FILE = path.join(__dirname, "AKUN.txt");
const PREMIUM_FILE = path.join(__dirname, "PREMIUM.txt");

const readAccounts = () => {
  try {
    return fs.readFileSync(AKUN_FILE, "utf-8")
      .split("\n")
      .filter(e => e.trim() && !e.trim().startsWith("//"))
      .map(e => {
        let a = e.trim().split(" ");
        let t = a[0];
        a = a[1];
        return t && a && t.includes("@") ? { email: t, pass: a, fullLine: e.trim() } : null;
      })
      .filter(e => e !== null);
  } catch (e) {
    console.error("❌ Gagal membaca AKUN.txt:", e.message);
    return [];
  }
};

const removeAccountFromFile = async (email) => {
  try {
    let e = fs.readFileSync(AKUN_FILE, "utf-8")
      .split("\n")
      .filter(e => !e.includes(email))
      .join("\n");
    fs.writeFileSync(AKUN_FILE, e);
    console.log(`🗑️ Akun ${email} dihapus dari AKUN.txt`);
  } catch (e) {
    console.error(`❌ Gagal menghapus akun ${email}:`, e.message);
  }
};

const savePremiumNew = async (email, pass) => {
  try {
    let e = [];
    e = fs.existsSync(PREMIUM_FILE) ? fs.readFileSync(PREMIUM_FILE, "utf-8").split("\n").filter(e => e.trim()) : e;
    if (!e.some(a => a.includes(email))) {
      e.push(email + " " + pass);
      fs.writeFileSync(PREMIUM_FILE, e.join("\n") + "\n");
      console.log(`✅ [PREMIUM BARU] ${email} disimpan ke PREMIUM.txt`);
      await kirimTelegram(`✅ *Premium Berhasil:*\n\`${email}\``);
    }
    await removeAccountFromFile(email);
  } catch (e) {
    console.error("❌ Gagal simpan premium baru:", e.message);
  }
};

const savePremiumExisting = async (email, pass) => {
  try {
    let e = [];
    e = fs.existsSync(PREMIUM_FILE) ? fs.readFileSync(PREMIUM_FILE, "utf-8").split("\n").filter(e => e.trim()) : e;
    if (!e.some(a => a.includes(email))) {
      e.push(email + ` ${pass} [ PREMIUM DULUAN ]`);
      fs.writeFileSync(PREMIUM_FILE, e.join("\n") + "\n");
      console.log(`✅ [PREMIUM DULUAN] ${email} disimpan ke PREMIUM.txt`);
      await kirimTelegram(`🏅 *Sudah Premium:*\n\`${email}\``);
    }
    await removeAccountFromFile(email);
  } catch (e) {
    console.error("❌ Gagal simpan premium duluan:", e.message);
  }
};

const kirimTelegram = async (text) => {
  let url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendMessage`;
  try {
    await axios.post(url, { chat_id: TELEGRAM_CHAT_ID, text: text, parse_mode: "Markdown" });
  } catch (e) {
    console.error("❌ Gagal kirim Telegram:", e.message);
  }
};

const kirimFileTelegram = async (filePath) => {
  let url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendDocument`;
  try {
    if (fs.statSync(filePath).size === 0) {
      console.log(`⚠️ File ${path.basename(filePath)} kosong, tidak dikirim`);
      return;
    }
    let form = new FormData();
    let stream = fs.createReadStream(filePath);
    form.append("chat_id", TELEGRAM_CHAT_ID);
    form.append("document", stream, { filename: path.basename(filePath), contentType: "text/plain" });
    
    let caption = filePath.includes("PREMIUM.txt") ? "✅ *File PREMIUM.txt*\nBerisi akun-akun yang berhasil Premium" : "📁 File hasil AutoPay";
    form.append("caption", caption);
    
    let response = await axios.post(url, form, { headers: form.getHeaders() });
    if (response.data.ok) console.log(`✅ File ${path.basename(filePath)} berhasil dikirim ke Telegram`);
  } catch (e) {
    console.error("❌ Error mengirim file:", e.message);
  }
};

const delay = (ms) => new Promise(res => setTimeout(res, ms));

const askThreadCount = () => {
    if (process.argv.includes("--auto")) {
        console.log("🤖 Mode Auto terdeteksi! Menjalankan dengan 1 thread.");
        return Promise.resolve(1); 
    }

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });
    return new Promise(resolve => {
        rl.question("🧵 Mau pakai berapa thread (1-10)? ", answer => {
            rl.close();
            const count = parseInt(answer);
            if (isNaN(count) || count < 1 || count > 10) {
                console.log("❌ Input tidak valid. Masukkan angka 1 - 10.");
                process.exit(1);
            }
            resolve(count);
        });
    });
};

const loginToGoogle = async (email, password, profilePath) => {
  let browser;
  try {
    browser = await puppeteer.launch({
      headless: IS_HEADLESS ? "new" : false,
      args: [
        "--user-data-dir=" + profilePath, "--no-sandbox", "--start-minimized", 
        "--disable-setuid-sandbox", "--disable-dev-shm-usage", "--disable-accelerated-2d-canvas", 
        "--disable-accelerated-jpeg-decoding", "--disable-web-security", 
        "--disable-features=IsolateOrigins,site-per-process", "--ignore-certificate-errors", 
        "--lang=US", "--disable-blink-features=AutomationControlled", "--no-first-run", 
        "--no-default-browser-check", "--disable-popup-blocking", "--disable-background-networking", 
        "--disable-background-timer-throttling", "--metrics-recording-only", 
        "--safebrowsing-disable-auto-update", "--disable-sync", "--disable-translate", 
        "--disable-default-apps", "--disable-extensions", "--disable-component-extensions-with-background-pages", 
        "--disable-client-side-phishing-detection", "--disable-crash-reporter", 
        "--disable-features=TranslateUI,BlinkGenPropertyTrees,PasswordImport,OptimizationHints,MediaRouter,AutomationControlled"
      ],
      defaultViewport: null,
      ignoreDefaultArgs: ["--enable-automation", "--disable-extensions-except"]
    });

    let page = await browser.newPage();
    await page.setExtraHTTPHeaders({
      "Accept-Language": "en-US,en;q=0.9",
      "Accept-Encoding": "gzip, deflate, br",
      "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8",
      "Connection": "keep-alive",
      "Upgrade-Insecure-Requests": "1"
    });

    // Stealth bypass
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, "webdriver", { get: () => false });
      Object.defineProperty(navigator, "plugins", { get: () => [1, 2, 3, 4, 5] });
      Object.defineProperty(navigator, "languages", { get: () => ["en-US", "en"] });
      window.chrome = { runtime: {} };
      let originalQuery = window.navigator.permissions.query;
      window.navigator.permissions.query = e => e.name === "notifications" ? Promise.resolve({ state: Notification.permission }) : originalQuery(e);
    });

    console.log(`\n[BROWSER] ${email}`);
    console.log("----------------------------------------------");
    await page.goto("https://accounts.google.com/", { waitUntil: "networkidle2" });
    console.log("⏳ Proses Login...");
    await delay(2000);
    await page.type("input#identifierId", email, { delay: 100 });
    
    await page.evaluate(() => {
      let btn = Array.from(document.querySelectorAll("button")).find(b => {
        let span = b.querySelector("span");
        return span && span.textContent.trim() === "Next";
      });
      if (btn) btn.click();
    });

    await delay(5000);
    console.log("⏳ Menunggu element password siap...");
    await page.waitForSelector('input[name="Passwd"]', { timeout: 30000, visible: true });

    let isPasswordReady = false;
    let attempts = 0;
    while (!isPasswordReady && attempts < 5) {
      try {
        let notDisabled = await page.$eval('input[name="Passwd"]', e => !e.disabled);
        let isVisible = await page.$eval('input[name="Passwd"]', e => {
          let style = window.getComputedStyle(e);
          return style.display !== "none" && style.visibility !== "hidden";
        });
        if (notDisabled && isVisible) {
          isPasswordReady = true;
        } else {
          console.log(`⏳ Element belum siap, tunggu 1 detik... (percobaan ${attempts + 1}/5)`);
          await delay(1000);
          attempts++;
        }
      } catch (e) {
        console.log("⚠️ Error cek element: " + e.message);
        await delay(1000);
        attempts++;
      }
    }

    if (!isPasswordReady) console.log("⚠️ Element password tidak siap, coba tetap lanjut...");
    await page.$eval('input[name="Passwd"]', e => e.value = "");
    console.log("✔ Mengisi password...");
    await page.type('input[name="Passwd"]', password, { delay: 150 });

    let filledPassword = await page.$eval('input[name="Passwd"]', e => e.value);
    if (filledPassword !== password) {
      console.log(`⚠️ Password tidak terisi sempurna. Diharapkan: ${password}, Terisi: ${filledPassword}`);
      console.log("⏳ Mencoba mengisi ulang...");
      await page.$eval('input[name="Passwd"]', e => e.value = "");
      await delay(500);
      await page.type('input[name="Passwd"]', password, { delay: 150 });
      if (await page.$eval('input[name="Passwd"]', e => e.value) !== password) {
        console.log("❌ Gagal mengisi password dengan benar");
      } else {
        console.log("✔ Password berhasil diisi ulang dengan benar");
      }
    } else {
      console.log("✔ Password terisi");
    }

    await page.evaluate(() => {
      let btn = Array.from(document.querySelectorAll("button")).find(b => {
        let span = b.querySelector("span");
        return span && span.textContent.trim() === "Next";
      });
      if (btn) btn.click();
    });

    await delay(5000);
    let isLoggedIn = false;
    for (let i = 0; i < 20; i++) {
      let url = page.url();
      if (url.includes("myaccount.google.com") || url.includes("accounts.google.com/signin/v2/challenge")) {
        isLoggedIn = true;
        break;
      }
      await delay(1000);
    }

    if (isLoggedIn) {
      console.log(`✔ Akun ${email} berhasil login.`);
      return { success: true, browser: browser, page: page, email: email, password: password };
    } else {
      console.log(`✖ Akun ${email} gagal login.`);
      await browser.close();
      rimraf.sync(profilePath);
      return { success: false, email: email, password: password };
    }
  } catch (e) {
    console.error(`✖ Error pada akun ${email}: ` + e.message);
    if (browser) await browser.close();
    rimraf.sync(profilePath);
    return { success: false, email: email, password: password };
  }
};

const processYouTubeAutoPay = async ({ email, pass }, index) => {
  let tempDir = path.join(__dirname, "TEMP");
  if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });
  let profilePath = path.join(tempDir, `profile-${index}-${Date.now()}`);

  console.log(`\n🔵 [${index}] Memproses: ${email}`);
  let loginResult = await loginToGoogle(email, pass, profilePath);
  
  if (!loginResult.success) return { email: email, success: false, reason: "LOGIN GAGAL" };
  
  let { browser, page } = loginResult;
  try {
    console.log(`⏳ [${email}] Mengakses Youtube...`);
    await page.goto("https://music.youtube.com/youtube_premium/student", { waitUntil: "networkidle2" });
    await delay(3000);
    
    if (page.url().includes("youtube.com/oops") || page.url().includes("/oops")) {
      console.log(`⚠️ [${email}] Redirect ke /oops - akun tidak dapat mengakses halaman student`);
      return { email: email, success: false, reason: "GAGAL OOPS" };
    }

    console.log(`⏳ [${email}] Mencari tombol pendaftaran...`);
    try {
      let btnClicked = await page.evaluate(() => {
        let texts = ["Lanjutkan dengan Mendaftar", "Continue With Signup", "Continue with Signup", "Lanjutkan", "Continue"];
        for (let el of document.querySelectorAll("button")) {
          let text = el.textContent || "";
          for (let target of texts) {
            if (text.includes(target)) {
              el.click();
              console.log(`✔ Tombol "${target}" diklik`);
              return true;
            }
          }
        }
        return false;
      });

      if (!btnClicked) {
        console.log(`⏳ [${email}] Sepertinya sudah Premium duluan, Aku cek dlu yaa..`);
        await page.goto("https://music.youtube.com/paid_memberships", { waitUntil: "networkidle2" });
        await delay(3000);
        let isPremium = await page.evaluate(() => {
          for (let el of document.querySelectorAll("yt-formatted-string#text.style-scope.ytmusic-toggle-button-renderer")) {
            let text = el.textContent.trim();
            if (text.includes("Kelola langganan") || text.includes("Manage subscription")) return true;
          }
          return false;
        });

        if (isPremium) {
          console.log(`🏅 [${email}] Sudah Premium duluan Bjirt`);
          await savePremiumExisting(email, pass);
        } else {
          console.log(`⚠ [${email}] Tombol daftar tidak ditemukan & bukan premium`);
        }
        return { email: email, success: false, alreadyPremium: true };
      }
      console.log(`✔ [${email}] Tombol pendaftaran berhasil diklik`);
    } catch (e) {
      console.log(`⚠ [${email}] Error klik tombol: ` + e.message);
      return { email: email, success: false, alreadyPremium: true };
    }

    console.log(`⏳ [${email}] Menunggu...`);
    await delay(5000);
    
    try {
      await page.waitForSelector("iframe#buyFlowDivIdIframe", { timeout: 10000 });
      let iframeElement = await page.$("iframe#buyFlowDivIdIframe");
      let frame = await iframeElement.contentFrame();
      if (!frame) throw new Error("Tidak dapat mengakses");
      console.log(`✔ [${email}] Berhasil mengakses`);
      
      let buyClicked = await frame.evaluate(() => {
        let texts = ["Beli", "Buy"];
        for (let el of document.querySelectorAll("span.VfPpkd-vQzf8d")) {
          let text = el.textContent.trim();
          if (texts.includes(text)) {
            let btn = el.closest("button");
            if (btn) {
              btn.click();
              return true;
            }
          }
        }
        return false;
      });

      if (!buyClicked) {
        console.log(`⚠ [${email}] Tombol "Beli/Buy" tidak ditemukan`);
        return { email: email, success: false, reason: "TOMBOL BELI TIDAK DITEMUKAN" };
      }
      console.log(`✔ [${email}] Tombol "Beli/Buy" berhasil diklik`);
    } catch (e) {
      console.log(`⚠ [${email}] Error iframe: ` + e.message);
      return { email: email, success: false, reason: "IFRAME ERROR" };
    }

    console.log(`⏳ [${email}] Menunggu response...`);
    await delay(5000);
    
    let errorMsg = null;
    try {
      let iframeElement = await page.$("iframe#buyFlowDivIdIframe");
      let frame = iframeElement ? await iframeElement.contentFrame() : null;
      if (frame) {
        errorMsg = await frame.evaluate(() => {
          let selectors = ['div[id^="id-"][data-ur].n806', "div.d2Nfqe", 'div[jsname="Cjx5Nb"]', "div.LXRPh", 'span[jsslot] div[role="alert"]'];
          for (let sel of selectors) {
            let el = document.querySelector(sel);
            if (el) {
              let text = el.textContent.trim();
              if (text.length > 0 && text.length < 400) return text;
            }
          }
          for (let el of document.querySelectorAll("div, span, p")) {
            if (el.children.length <= 3) {
              let text = el.textContent.trim();
              if (text.length > 0 && text.length <= 300) {
                if (text.includes("OR_FGVEM_21") || text.includes("OR_PMCR_32") || text.includes("Saldo rekening Anda tidak akan menutupi") || text.includes("Transaksi Anda tidak dapat diselesaikan")) {
                  return text;
                }
              }
            }
          }
          return null;
        });
      }
    } catch (e) {
      console.log(`⚠️ [${email}] Gagal cek error di iframe: ` + e.message);
    }

    if (errorMsg) {
      console.log(`📝 [${email}] Pesan error: ` + errorMsg);
      if (errorMsg.includes("Saldo rekening Anda tidak akan menutupi pembayaran") || errorMsg.includes("OR_FGVEM_21")) {
        console.log(`⚠️ [${email}] Saldo Gopay Kurang`);
        return { email: email, success: false, reason: "SALDO KURANG" };
      } else if (errorMsg.includes("Transaksi Anda tidak dapat diselesaikan") || errorMsg.includes("OR_PMCR_32")) {
        console.log(`🤖 [${email}] Transaksi ditolak`);
        return { email: email, success: false, reason: "DITOLAK" };
      } else {
        console.log(`❓ [${email}] Error tidak dikenal: ` + errorMsg);
        return { email: email, success: false, reason: "ERROR LAIN" };
      }
    }

    console.log(`⏳ [${email}] Menunggu dialog konfirmasi premium...`);
    let successTexts = ["Selamat datang di YouTube Premium", "Welcome to YouTube Premium"];
    let isSuccess = false;
    try {
      await page.waitForFunction(texts => {
        let title = document.querySelector("yt-formatted-string#title.style-scope.yt-confirm-dialog-renderer");
        return !!title && texts.some(t => title.textContent.trim().includes(t));
      }, { timeout: 10000 }, successTexts);
      isSuccess = true;
    } catch (e) {
      isSuccess = false;
    }

    if (isSuccess) {
      console.log(`✅ [${email}] BERHASIL PAY TRIAL!.`);
      await savePremiumNew(email, pass);
      return { email: email, success: true, isPremium: true };
    } else {
      console.log(`⚠️ [${email}] Tidak ada error & tidak ada dialog sukses. Status tidak jelas.`);
      return { email: email, success: false, reason: "STATUS TIDAK JELAS" };
    }

  } catch (e) {
    console.log(`🚫 Error akun ${email}: ` + e.message);
    return { email: email, success: false, reason: "ERROR" };
  } finally {
    try { if (browser) await browser.close(); } catch (e) { console.log("⚠️ Error saat tutup browser:", e.message); }
    try { if (fs.existsSync(profilePath)) rimraf.sync(profilePath); } catch (e) {}
  }
};

const processAccountsInBatches = async (accounts, threadCount) => {
  let batchIndex = 0, successCount = 0, alreadyPremiumCount = 0;
  let failedAccounts = [];

  while (accounts.length > 0) {
    console.log(`\n🚀 Batch ${batchIndex + 1}`);
    let batch = accounts.splice(0, threadCount).map((acc, i) => new Promise(resolve => {
      setTimeout(async () => {
        let result = await processYouTubeAutoPay(acc, i + 1);
        if (result.isPremium) successCount++;
        else if (result.alreadyPremium) alreadyPremiumCount++;
        else failedAccounts.push({ email: acc.email, reason: result.reason });
        resolve();
      }, 2000 * i);
    }));
    await Promise.all(batch);
    batchIndex++;
  }

  console.log("\n" + "=".repeat(50));
  console.log("📊 RINGKASAN YOUTUBE AUTO PAY");
  console.log("=".repeat(50));
  console.log(`✅ Premium Baru    : ${successCount} akun`);
  console.log(`✅ Sudah Premium   : ${alreadyPremiumCount} akun`);
  console.log(`❌ Gagal           : ${failedAccounts.length} akun`);

  if (failedAccounts.length > 0) {
    console.log("\n📋 Detail Akun Gagal:");
    failedAccounts.forEach((acc, i) => {
      console.log(`  ${i + 1}. ${acc.email} - ${acc.reason || "Unknown"}`);
    });
  }

  if (successCount > 0 && fs.existsSync(PREMIUM_FILE)) {
    await kirimFileTelegram(PREMIUM_FILE);
  }

  await kirimTelegram(`📊 *RINGKASAN YOUTUBE AUTO PAY*\n✅ Premium Baru: ${successCount}\n✅ Sudah Premium: ${alreadyPremiumCount}\n❌ Gagal: ${failedAccounts.length}`);
};

process.on("unhandledRejection", e => console.error("⚠️ Unhandled Rejection:", e));
process.on("uncaughtException", e => console.error("⚠️ Uncaught Exception:", e));

(async () => {
  console.log("\n" + "=".repeat(50));
  console.log("🎬 YOUTUBE AUTO PAY BOT BY SINDU SAGA");
  console.log("=".repeat(50));

  if (!fs.existsSync(AKUN_FILE)) { fs.writeFileSync(AKUN_FILE, ""); console.log("📁 File AKUN.txt dibuat"); }
  if (!fs.existsSync(PREMIUM_FILE)) { fs.writeFileSync(PREMIUM_FILE, ""); console.log("📁 File PREMIUM.txt dibuat"); }

  let tempDir = path.join(__dirname, "TEMP");
  if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

  let accounts = readAccounts();
  if (accounts.length === 0) {
    console.log("❌ Tidak ada akun valid di AKUN.txt\n📝 Format: email@example.com password");
    process.exit(1);
  }

  console.log(`📋 Total ${accounts.length} akun akan diproses`);
  console.log("🖥️ Headless mode: " + (IS_HEADLESS ? "Ya" : "Tidak"));

  await kirimTelegram(`🚀 *Memulai YouTube Auto Pay*\nTotal akun: ${accounts.length}\nHeadless: ${IS_HEADLESS ? "Ya" : "Tidak"}`);
  
  let threadCount = await askThreadCount();
  await processAccountsInBatches(accounts, threadCount);

  if (fs.existsSync(tempDir)) {
    fs.rmSync(tempDir, { recursive: true, force: true });
    console.log("🧹 Folder TEMP dibersihkan");
  }
  console.log("\n✨ Semua proses selesai!");
})();
